import{_ as s,o as t,c as i,a0 as a}from"./chunks/framework.ZNXClGez.js";const u=JSON.parse('{"title":"Quick Start","description":"","frontmatter":{},"headers":[],"relativePath":"guide/development/quick-start.md","filePath":"guide/development/quick-start.md"}'),o={name:"guide/development/quick-start.md"};function n(l,e,r,h,d,p){return t(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="quick-start" tabindex="-1">Quick Start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick Start&quot;">​</a></h1><p>This section will guide you through a quick setup process to get started with development and provide details on fully configuring your development environment.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><p>Ensure the following software is installed on your system:</p><ul><li><a href="https://git-scm.com/" target="_blank" rel="noreferrer">Git</a></li><li><a href="https://nodejs.org/" target="_blank" rel="noreferrer">Node.js</a> (<code>^22.13.0 || ^23.5.0 || &gt;=24.0.0</code>)</li></ul><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h2><h3 id="_1-clone-the-repository" tabindex="-1">1. Clone the Repository <a class="header-anchor" href="#_1-clone-the-repository" aria-label="Permalink to &quot;1. Clone the Repository&quot;">​</a></h3><p>Clone the Authup repository to a local directory using Git:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/authup/authup</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> </span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> authup</span></span></code></pre></div><h3 id="_2-install-dependencies" tabindex="-1">2. Install Dependencies <a class="header-anchor" href="#_2-install-dependencies" aria-label="Permalink to &quot;2. Install Dependencies&quot;">​</a></h3><p>Install all required (dev-) dependencies for the monorepo.</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> i</span></span></code></pre></div><h3 id="_3-start-the-development-servers" tabindex="-1">3. Start the Development Servers <a class="header-anchor" href="#_3-start-the-development-servers" aria-label="Permalink to &quot;3. Start the Development Servers&quot;">​</a></h3><p>Start the backend in development mode using the CLI.</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cli-dev</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --workspace=apps/server-core</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre></div><p>This runs the server from its TypeScript source through <code>ts-node</code> (no build step) and serves the hosted auth pages (<code>/authorize</code>, <code>/register</code>, ...) from the <code>apps/client-auth-console</code> source through an embedded vite dev server, so an edit there shows up on the next request. The <code>@authup/*</code> packages are still resolved from their built <code>dist/</code>, so run <code>npm run build</code> once after pulling. Expect a <code>--experimental-loader</code> warning on start; it is harmless. To run the built server instead, use <code>npm run build --workspace=apps/server-core</code> followed by <code>npm run cli --workspace=apps/server-core -- start</code>.</p><p>The backend also serves the admin console at <code>http://localhost:3001/console/admin</code> and the account console at <code>http://localhost:3001/console/account</code>, from the built bundle of each package. Build the admin console BEFORE starting the backend (and restart the backend after rebuilding it): the asset mount is decided at boot, so a bundle built afterwards is not served until the next start.</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --workspace=apps/client-admin-console</span></span></code></pre></div><p>To work on the admin console itself, run its vite dev server instead. It gives you hot module replacement and talks to the backend across origins:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> VITE_API_URL=http://localhost:3001</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --workspace=apps/client-admin-console</span></span></code></pre></div><p>Now you should have the backend and the console dev server running locally.</p><ul><li><strong>Admin console (dev server)</strong> <code>http://localhost:3000/console/admin/</code></li><li><strong>Admin console (served)</strong> <code>http://localhost:3001/console/admin</code></li><li><strong>Account console</strong> <code>http://localhost:3001/console/account</code></li><li><strong>Backend</strong> <code>http://localhost:3001/</code></li><li><strong>Swagger-Docs</strong> <code>http://localhost:3001/docs</code></li><li><strong>Prometheus-Metrics</strong> <code>http://localhost:3001/metrics</code></li></ul><p>The dev server&#39;s origin (<code>http://localhost:3000</code>) is trusted automatically outside production, so its login redirect works without any configuration. Because it is a different origin than the API, it signs in with the browser-side authorization-code flow rather than the server session cookie the served console uses.</p><p>You can start working with the application or begin making contributions to the project!</p>`,24)])])}const k=s(o,[["render",n]]);export{u as __pageData,k as default};
